INSERT INTO public.products (name, brand, description, size_ml, category, target_area, metadata)
VALUES
('Clinea Hyaluronic Waterbomb Face Booster 30ml', 'Clinea', 'Αυτό είναι ένα συμπυκνωμένο ενυδατικό booster που ξεδιψά και αναζωογονεί την επιδερμίδα. 98% συστατικά φυσικής προέλευσης.', 30, 'Hydration', '{face}', '{"greek_title":"Clinea Hyaluronic Waterbomb Καταπραϋντικό & Αντιγηραντικό Booster Προσώπου με Υαλουρονικό Οξύ για Αναζωογόνηση 30ml","ingredients":"Δραστικό Συστατικό Υαλουρονικό Οξύ","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι","vegan":false,"cruelty_free":false,"image_url":"https://b.scdn.gr/images/sku_main_images/040897/40897837/xlarge_20230316123754_clinea_hyaluronic_waterbomb_enydatiko_serum_prosopou_me_yalouroniko_oxy_30ml.jpeg","source":"Skroutz CSV"}'),
('Beauty of Joseon Revive Ginseng & Retinal Eye Serum 30ml', 'Beauty of Joseon', 'Ορός ματιών με αντιγηραντική δράση της Beauty of Joseon (Korean Skincare), που έχει σχεδιαστεί για να μετριάζει τις ρυτίδες γύρω από τα μάτια, συνδυάζοντας εκχύλισμα ginseng και ρετινάλη.', 30, 'Hydration', '{body}', '{"greek_title":"Beauty of Joseon Revive Ginseng & Retinal Ενυδατικό & Αντιγηραντικό Serum Ματιών με Ρετινάλη & Νιασιναμίδη για Αναζωογόνηση 30ml","ingredients":"Δραστικό Συστατικό Νιασιναμίδη, Ρετινάλη","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι","vegan":false,"cruelty_free":false,"image_url":"https://b.scdn.gr/images/sku_main_images/039248/39248946/xlarge_20230822163501_beauty_of_joseon_revive_inseng_retinal_antigirantiko_serum_mation_30ml.jpeg","source":"Skroutz CSV"}'),
('Celimax The Vita-A Retinal Shot Tightening Face Booster 15ml', 'Celimax', 'Ο Celimax The Vita-A Retinal Shot Tightening Booster είναι ένας ορός προσώπου 15 ml που περιέχει ρετινάλη. Σχεδιάστηκε για να συμβάλλει στη σύσφιξη της επιδερμίδας και στη βελτίωση της υφής της, μειώνοντας την εμφάνιση λεπτών γραμμών και ρυτίδων. Η ρετινόλη, μια μορφή βιταμίνης Α, είναι γνωστή για τις ιδιότητές της στην ανανέωση των κυττάρων του δέρματος.', 15, 'Hydration', '{face}', '{"greek_title":"Celimax The Vita-A Retinal Shot Tightening Ενυδατικό & Αντιγηραντικό Booster Προσώπου με Ρετινάλη για Σύσφιξη & Θρέψη 15ml","ingredients":"Δραστικό Συστατικό Ρετινάλη","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι, Ευαίσθητη","vegan":false,"cruelty_free":false,"image_url":"https://c.scdn.gr/images/sku_main_images/060527/60527403/xlarge_20250521163510_celimax_the_vita_a_retinal_shot_tightening_booster_prosopou_me_retinali_retinoli_gia_sysfixi_15ml.jpeg","source":"Skroutz CSV"}'),
('Beauty of Joseon Propolis + Niacinamide Face Essence 30ml', 'Beauty of Joseon', 'Ορός προσώπου Propolis + Niacinamide της κορεάτικης εταιρίας Beauty of Joseon (Korean beauty). Η πρόπολη και η νιασιναμίδη καταπραΰνουν τη φλεγμονή και προσδίδουν στην επιδερμίδα όμορφη λάμψη.', 30, 'Hydration', '{face}', '{"greek_title":"Beauty of Joseon Propolis + Niacinamide Καταπραϋντικό & Ενυδατικό Essence Προσώπου με Centella Asiatica & Νιασιναμίδη για Λάμψη 30ml","ingredients":"Δραστικό Συστατικό Νιασιναμίδη, Centella Asiatica","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι","vegan":false,"cruelty_free":false,"image_url":"https://d.scdn.gr/images/sku_main_images/031947/31947514/xlarge_20221020133727_beauty_of_joseon_propolis_niacinamide_serum_prosopou_30ml.jpeg","source":"Skroutz CSV"}'),
('La Roche Posay Effaclar Ultra Concentrated Face Serum 30ml', 'La', 'Ορός υψηλής συγκέντρωσης Effaclar Serum για βέλτιστη αποτελεσματικότητα στη μείωση των ατελειών, χάρη σε ένα σύμπλοκο τριών οξέων σε υψηλή συγκέντρωση. Καθημερινή απολέπιση, για βελτίωση της υφής του δέρματος από το 1ο πρωί. Σύνθεση που δεν προκαλεί ατέλειες, δηλαδή δε φράζει τους πόρους.', 30, 'Skincare', '{face}', '{"greek_title":"La Roche Posay Effaclar Ultra Concentrated Serum Προσώπου με AHA & Σαλικυλικό Οξύ για Ακμή & Ατέλειες 30ml","ingredients":"Δραστικό Συστατικό Σαλικυλικό Οξύ, AHA","skin_type":"Τύπος Επιδερμίδας Ακνεϊκή","vegan":false,"cruelty_free":false,"image_url":"https://c.scdn.gr/images/sku_main_images/024707/24707855/xlarge_20260313114947_la_roche_posay_effaclar_ultra_concentrated_serum_prosopou_me_aha_salikyliko_oxy_gia_akmi_ateleies_30ml.jpeg","source":"Skroutz CSV"}'),
('La Roche Posay Retinol B3 Face Serum 30ml', 'La', 'Αντιρυτιδικός ορός αναδόμησης & ανάπλασης, ακόμα και για το ευαίσθητο δέρμα. Διορθώνει τις βαθιές ρυτίδες, τις λεπτές γραμμές και τον ανομοιόμορφο τόνο της επιδερμίδας.', 30, 'Anti-Aging', '{face}', '{"greek_title":"La Roche Posay Retinol B3 Αντιγηραντικό Serum Προσώπου με Ρετινόλη & Νιασιναμίδη 30ml","ingredients":"Δραστικό Συστατικό Ρετινόλη, Νιασιναμίδη","skin_type":"Τύπος Επιδερμίδας Ευαίσθητη","vegan":false,"cruelty_free":false,"image_url":"https://b.scdn.gr/images/sku_main_images/023595/23595928/xlarge_20260313114944_la_roche_posay_retinol_b3_antigirantiko_serum_prosopou_me_retinoli_niasinamidi_30ml.jpeg","source":"Skroutz CSV"}'),
('Vichy Liftactiv Specialist B3 Face Serum 30ml', 'Vichy', '', 30, 'Anti-Aging', '{face}', '{"greek_title":"Vichy Liftactiv Specialist B3 Αντιγηραντικό Serum Προσώπου με Νιασιναμίδη για Lifting & Πανάδες 30ml","ingredients":"Δραστικό Συστατικό Νιασιναμίδη","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι","vegan":false,"cruelty_free":false,"image_url":"https://d.scdn.gr/images/sku_main_images/033358/33358691/xlarge_20260313115010_vichy_liftactiv_specialist_b3_antigirantiko_serum_prosopou_me_niasinamidi_gia_lifting_panades_30ml.jpeg","source":"Skroutz CSV"}'),
('Haruharu Wonder Black Rice Probiotics Barrier Face Essence 120ml', 'Haruharu', 'Το Haruharu Wonder Black Rice Probiotics Barrier Essence είναι ένας ορός προσώπου που στοχεύει στη σύσφιξη και ενίσχυση του όγκου της επιδερμίδας. Περιέχει σύμπλεγμα 5 Ceramide Complex και 5 Fatty Acids Complex, τα οποία συμβάλλουν στην αναπλήρωση του δερματικού φραγμού, προσφέροντας μια ενυδατωμένη και λεία επιδερμίδα χωρίς αίσθηση κολλώδους.', 120, 'Hydration', '{face}', '{"greek_title":"Haruharu Wonder Black Rice Probiotics Barrier Καταπραϋντικό & Ενυδατικό Essence Προσώπου για Αποτοξίνωση & Σύσφιξη 120ml","ingredients":"Τύπος Επιδερμίδας Όλοι οι Τύποι","skin_type":"Αμπούλες Όχι","vegan":false,"cruelty_free":false,"image_url":"https://c.scdn.gr/images/sku_main_images/057629/57629227/xlarge_20241125121437_haruharu_wonder_black_rice_probiotics_barrier_essence_prosopou_gia_sysfixi_120ml.jpeg","source":"Skroutz CSV"}'),
('Axis-y Dark Spot Correcting Glow Face Serum', 'Axis-y', 'Ένας ορός με βάση τη νιασιναμίδη 5% που διορθώνει τις σκούρες κηλίδες και βελτιώνει τον ανομοιόμορφο τόνο του δέρματος. Με τη βοήθεια της σκουαλάνης - φυτικής προέλευσης, αυτός ο ορός διατηρεί την υγρασία για να διατηρεί το δέρμα σας λαμπερό και υγιές όπου κι αν πάτε.', 50, 'Hydration', '{face}', '{"greek_title":"Axis-y Dark Spot Correcting Glow Ενυδατικό Serum Προσώπου με Νιασιναμίδη για Λάμψη & Πανάδες 50ml","ingredients":"Δραστικό Συστατικό Νιασιναμίδη","skin_type":"Αμπούλες Όχι","vegan":false,"cruelty_free":false,"image_url":"https://d.scdn.gr/images/sku_main_images/045729/45729180/xlarge_20230911165441_axis_y_serum_prosopou_gia_lampsi_panades_50ml.jpeg","source":"Skroutz CSV"}'),
('Cosrx The 6 Peptide Face Essence', 'Cosrx', 'To Cosrx The 6 peptide skin booster serum είναι ένας πολύ λεπτόρρευστος ενυδατικός ορός με 6 ισχυρά πεπτίδια που ενισχύει τη συνολική κατάσταση του δέρματος και λειτουργεί ως πρώτος ορός για να προετοιμάσει και να ενισχύσει την δράση των συμπυκνωμένων στοιχείων που θα ακολουθήσουν. Έξι πεπτίδια που αποκαθιστούν και αντιμετωπίζουν πολλαπλά...', 150, 'Hydration', '{face}', '{"greek_title":"Cosrx The 6 Peptide Καταπραϋντικό & Αντιγηραντικό Essence Προσώπου με Πεπτίδια για Λάμψη & Σύσφιξη 150ml","ingredients":"Δραστικό Συστατικό Πεπτίδια","skin_type":"Τύπος Επιδερμίδας Ευαίσθητη","vegan":false,"cruelty_free":false,"image_url":"https://c.scdn.gr/images/sku_main_images/048434/48434942/xlarge_20240130090755_cosrx_booster_prosopou_150ml.jpeg","source":"Skroutz CSV"}'),
('Cerion Hyserum Face Serum 30ml', 'Cerion', 'O Cerion HY Serum Serum Hyaluronic Acid είναι ένας συμπυκνωμένος αντιγηραντικός ορός προσώπου για άμεση τόνωση και αποκατάσταση της επιδερμίδας. Διαθέτει εξαιρετικά αυξημένο ποσοστό Υαλουρονικού οξέος (56%) για μοναδικά αποτελέσματα σύσφιξης, ανόρθωσης και αναζωογόνησης. Αποτελεί μία σύνθεση κατάλληλη και για την ανδρική επιδερμίδα, ειδικά μετά το ξύρισμα.', 30, 'Anti-Aging', '{face}', '{"greek_title":"Cerion Hyserum Αντιγηραντικό Serum Προσώπου με Υαλουρονικό Οξύ για Lifting 30ml","ingredients":"Δραστικό Συστατικό Υαλουρονικό Οξύ","skin_type":"Τύπος Επιδερμίδας Αφυδατωμένη","vegan":false,"cruelty_free":false,"image_url":"https://b.scdn.gr/images/sku_main_images/031741/31741677/xlarge_20230105154508_cerion_hyserum_serum_prosopou_30ml.jpeg","source":"Skroutz CSV"}'),
('Skin1004 Madagascar Centella Probio-Cica Intensive Face Serum', 'Skin1004', 'Το Skin1004 Madagascar Centella Probio-Cica Intensive Ενυδατικό Serum Προσώπου είναι ένα εντατικό προϊόν περιποίησης που έχει σχεδιαστεί για να προσφέρει βαθιά ενυδάτωση και να συμβάλει στη σύσφιξη της επιδερμίδας. Περιέχει εκχύλισμα Centella Asiatica από τη Μαδαγασκάρη, γνωστό για τις καταπραϋντικές και αναπλαστικές του ιδιότητες. Η σύνθεσή του με το...', 50, 'Hydration', '{face}', '{"greek_title":"Skin1004 Madagascar Centella Probio-Cica Intensive Ενυδατικό Serum Προσώπου με Centella Asiatica για Σύσφιξη 50ml","ingredients":"Δραστικό Συστατικό Centella Asiatica","skin_type":"Τύπος Επιδερμίδας Ξηρή, Κανονική, Μικτή","vegan":false,"cruelty_free":false,"image_url":"https://d.scdn.gr/images/sku_main_images/057994/57994587/xlarge_20241216120940_skin1004_madagascar_centella_probio_cica_intensive_kataprayntiko_enydatiko_serum_prosopou_me_niasinamidi_50ml.jpeg","source":"Skroutz CSV"}'),
('Vichy Mineral 89 Probiotic Fractions Face Booster 30ml', 'Vichy', 'Booster ανάπλασης, το οποίο είναι εμπλουτισμένο με Κλάσματα Προβιοτικών, καθώς και με αντιοξειδωτικές βιταμίνες όπως η Νιασιναμίδη, για να επανορθώνει ορατά την υγιή όψη της επιδερμίδας.', 30, 'Hydration', '{face}', '{"greek_title":"Vichy Mineral 89 Probiotic Fractions Ενυδατικό & Αντιγηραντικό Booster Προσώπου με Νιασιναμίδη & Υαλουρονικό Οξύ για Αποτοξίνωση & Θρέψη 30ml","ingredients":"Δραστικό Συστατικό Υαλουρονικό Οξύ, Νιασιναμίδη","skin_type":"Αμπούλες Όχι","vegan":false,"cruelty_free":false,"image_url":"https://c.scdn.gr/images/sku_main_images/028821/28821744/xlarge_20260313115002_vichy_mineral_89_probiotic_fractions_enydatiko_antigirantiko_booster_prosopou_me_niasinamidi_yalouroniko_oxy_gia_apotoxinosi_threpsi_30ml.jpeg","source":"Skroutz CSV"}'),
('Vt Cosmetics Reedle Shot 300 50ml Εντατικός Ενισχυτής Ενδυνάμωσης', 'Vt', 'Serum περιποίησης δέρματος που μεταμορφώνει τη ρουτίνα περιποίησης της επιδερμίδας. Χρησιμοποιεί συστατικά με προηγμένη τεχνολογία microneedle που διεγείρουν απαλά το δέρμα για να παρέχουν καλύτερη απορρόφηση και μεγαλύτερη αποτελεσματικότητα στα βαθύτερα στρώματα του δέρματος.', 50, 'Anti-Aging', '{face}', '{"greek_title":"Vt Cosmetics Reedle Shot 300 50ml Εντατικός Ενισχυτής Ενδυνάμωσης","ingredients":"Δραστικό Συστατικό Υαλουρονικό Οξύ, Centella Asiatica","skin_type":"Τύπος Επιδερμίδας Ευαίσθητη","vegan":false,"cruelty_free":false,"image_url":"https://b.scdn.gr/images/sku_main_images/055768/55768062/xlarge_20240905145319_vt_cosmetics_reedle_shot_300_50ml_entatikos_enischytis_endynamosis.jpeg","source":"Skroutz CSV"}'),
('Vichy Liftactiv Collagen Specialist 16 Face Serum 30ml', 'Vichy', 'Ο ορός Liftactiv Collagen Specialist 16 Bonding αξιοποιεί την προηγμένη Τεχνολογία Co-Bonding για να ενισχύσει και να συνδέσει μεταξύ τους, τους διαφορετικούς τύπους κολλαγόνου, προσφέροντας σφριγηλή, λεία και αναζωογονημένη επιδερμίδα.', 30, 'Hydration', '{face}', '{"greek_title":"Vichy Liftactiv Collagen Specialist 16 Ενυδατικό & Αντιγηραντικό Serum Προσώπου με Νιασιναμίδη & Πεπτίδια για Λάμψη & Σύσφιξη 30ml","ingredients":"Δραστικό Συστατικό Πεπτίδια, Νιασιναμίδη","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι, Ευαίσθητη","vegan":false,"cruelty_free":false,"image_url":"https://c.scdn.gr/images/sku_main_images/058322/58322572/xlarge_20260313115109_vichy_liftactiv_collagen_specialist_16_enydatiko_antigirantiko_serum_prosopou_me_niasinamidi_peptidia_gia_lampsi_sysfixi_30ml.jpeg","source":"Skroutz CSV"}'),
('Beauty of Joseon Calming Face Serum 30ml', 'Beauty of Joseon', 'Αυτός ο ορός είναι σχεδιασμένος για να ανακουφίσει την ταλαιπωρία του δέρματος που προκαλείται από την έκθεση στην υπεριώδη ακτινοβολία και άλλους εξωτερικούς παράγοντες στρες.', 30, 'Hydration', '{face}', '{"greek_title":"Beauty of Joseon Calming Καταπραϋντικό & Ενυδατικό Serum Προσώπου με Green Tea & Panthenol για Αποτοξίνωση 30ml","ingredients":"Δραστικό Συστατικό Βιταμίνη B5","skin_type":"Τύπος Επιδερμίδας Ευαίσθητη, Όλοι οι Τύποι","vegan":false,"cruelty_free":false,"image_url":"https://d.scdn.gr/images/sku_main_images/031947/31947510/xlarge_20220322163950_beauty_of_joseon_green_tea_panthenol_serum_prosopou_30ml.jpeg","source":"Skroutz CSV"}'),
('Vichy Liftactiv Retinol Specialist A+ Deep Wrinkles Face Serum 30ml', 'Vichy', 'Ο Vichy Liftactiv Retinol Specialist A+ Deep Wrinkles Serum είναι ένας καινοτόμος ορός με 0.2% καθαρή ρετινόλη, ενισχυμένος με κλάσματα προβιοτικών και βιοπεπτίδια για εντατική αντιγηραντική δράση.', 30, 'Anti-Aging', '{face}', '{"greek_title":"Vichy Liftactiv Retinol Specialist A+ Deep Wrinkles Αντιγηραντικό Serum Προσώπου με Ρετινόλη για Λάμψη & Lifting 30ml","ingredients":"Δραστικό Συστατικό Ρετινόλη","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι","vegan":false,"cruelty_free":false,"image_url":"https://a.scdn.gr/images/sku_main_images/038940/38940984/xlarge_20260313115027_vichy_liftactiv_retinol_specialist_a_deep_wrinkles_antigirantiko_serum_prosopou_me_retinoli_gia_lampsi_lifting_30ml.jpeg","source":"Skroutz CSV"}'),
('Essence Face Essence 140ml', 'Essence', 'Το Mary & May Vegan Blackberry Complex Cream Essence είναι ένα διφασικό essence που προσφέρει τα οφέλη μιας θρεπτικής κρέμας με το αναζωογονητικό αποτέλεσμα ενός essence. Χρησιμοποιεί την αποκλειστική τεχνολογία Double Phase Emulsion της MARY & MAY για γρήγορη απορρόφηση στο δέρμα. Η πλούσια κρέμα διαλύεται στο ενυδατικό essence, σταθεροποιώντας όλα τα...', 140, 'Hydration', '{face}', '{"greek_title":"Essence Ενυδατικό Essence Προσώπου με Centella Asiatica & Υαλουρονικό Οξύ 140ml","ingredients":"Δραστικό Συστατικό Υαλουρονικό Οξύ, Centella Asiatica","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι","vegan":false,"cruelty_free":false,"image_url":"https://b.scdn.gr/images/sku_main_images/048780/48780890/xlarge_20240916100528_essence_enydatiki_krema_prosopou_140ml.jpeg","source":"Skroutz CSV"}'),
('La Roche Posay Pure Vitamin C12 Face Serum 30ml', 'La', 'Το PURE VITAMIN C12 Serum είναι ένας ισχυρός αντιρυτιδικός και αντιοξειδωτικός ορός με 12% καθαρή βιταμίνη C, σχεδιασμένος να επαναφέρει τη λάμψη και να βελτιώνει την ομοιομορφία του δέρματος. Με κλινικά αποδεδειγμένη αποτελεσματικότητα, μειώνει τις ρυτίδες, λειαίνει την υφή και χαρίζει πιο νεανική, φωτεινή επιδερμίδα.', 30, 'Anti-Aging', '{face}', '{"greek_title":"La Roche Posay Pure Vitamin C12 Αντιγηραντικό Serum Προσώπου με Βιταμίνη C & Σαλικυλικό Οξύ για Αποτοξίνωση & Λάμψη 30ml","ingredients":"Δραστικό Συστατικό Βιταμίνη C, Σαλικυλικό Οξύ","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι, Ευαίσθητη","vegan":false,"cruelty_free":false,"image_url":"https://b.scdn.gr/images/sku_main_images/056742/56742327/xlarge_20260313115055_la_roche_posay_pure_vitamin_c12_antigirantiko_serum_prosopou_me_vitamini_c_salikyliko_oxy_gia_apotoxinosi_lampsi_30ml.jpeg","source":"Skroutz CSV"}'),
('Geek & Gorogeous Face Serum 30ml', 'Geek', 'Ο ορός Power Peptides περιέχει τέσσερις τεχνολογίες πεπτιδίων σε κλινικά αποδεδειγμένα ποσοστά. Συνεργάζονται για να συσφίξουν το δέρμα, αυξάνοντας την σφριγηλότητα και την ελαστικότητα της επιδερμίδας, συμβάλλοντας στη μείωση των ρυτίδων και παρέχοντας ισχυρή αντιγήρανση μέσω της ενεργοποίησης παραγωγής κολλαγόνου. Αξιοσημείωτη είναι η μεταξένια,...', 30, 'Anti-Aging', '{face}', '{"greek_title":"Geek & Gorogeous Αντιγηραντικό Serum Προσώπου με Πεπτίδια για Λάμψη & Θρέψη 30ml","ingredients":"Δραστικό Συστατικό Πεπτίδια","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι","vegan":false,"cruelty_free":false,"image_url":"https://d.scdn.gr/images/sku_main_images/055765/55765414/xlarge_20240905134122_geek_gorogeous_antigirantiko_serum_prosopou_me_kollagono_gia_lampsi_30ml.jpeg","source":"Skroutz CSV"}'),
('Cosrx Advanced Snail 96 Face Essence 100ml', 'Cosrx', '', 100, 'Hydration', '{face}', '{"greek_title":"Cosrx Advanced Snail 96 Ενυδατικό & Αντιγηραντικό Essence Προσώπου με Έκκριμα Σαλιγκαριού για Λάμψη & Λεύκανση 100ml","ingredients":"Δραστικό Συστατικό Έκκριμα σαλιγκαριού","skin_type":"Τύπος Επιδερμίδας Όλοι οι Τύποι, Ευαίσθητη","vegan":false,"cruelty_free":false,"image_url":"https://d.scdn.gr/images/sku_main_images/020012/20012974/xlarge_20230127110916_cosrx_advanced_snail_96_enydatiko_serum_prosopou_100ml.jpeg","source":"Skroutz CSV"}'),
