('Bioderma Hydrabio Face Serum 40ml', 'Bioderma', 'Serum προσώπου που βοηθά στην ενυδάτωση και τη φυσική επαναφορά του δέρματος. Είναι κατάλληλο για όλους τους τύπους δέρματος, μόνο του ή συνδυασμένο με μια θεραπεία.', 40, 'Hydration', '{face}', '{"greek_title":"Bioderma Hydrabio Ενυδατικό Serum Προσώπου με Υαλουρονικό Οξύ για Λάμψη 40ml","ingredients":"Δραστικό Συστατικό Υαλουρονικό Οξύ","skin_type":"Τύπος Επιδερμίδας Ευαίσθητη, Αφυδατωμένη","vegan":false,"cruelty_free":false,"image_url":"https://a.scdn.gr/images/sku_main_images/005256/5256687/xlarge_20240301132159_bioderma_hydrabio_enydatiko_serum_prosopou_40ml.jpeg","source":"Skroutz CSV"}'),
('Frezyderm Face Tightener Face Serum 30ml', 'Frezyderm', 'Ορός σύσφιγξης, αναμόρφωσης και επαναπροσδιορισμού περιγράμματος με άμεσα και μακροπρόθεσμα συσφιγκτικά αποτελέσματα.', 30, 'Anti-Aging', '{face}', '{"greek_title":"Frezyderm Face Tightener Αντιγηραντικό Serum Προσώπου με Κολλαγόνο για Σύσφιξη 30ml","ingredients":"Δραστικό Συστατικό Κολλαγόνο","skin_type":"Τύπος Επιδερμίδας Μικτή","vegan":false,"cruelty_free":false,"image_url":"https://c.scdn.gr/images/sku_main_images/052205/52205824/xlarge_20240411133532_frezyderm_face_tightener_antigirantiko_serum_prosopou_me_kollagono_gia_sysfixi_30ml.jpeg","source":"Skroutz CSV"}'),
